before:
Complete local Go example; the app itself does not execute it:
```go
package main

import (
"fmt"
)

func produce(input []int, out chan<- int, done chan<- struct{}) {
    defer close(done)
    defer close(out)
    for _, minutes := range input {
        if minutes >= 1 && minutes <= 60 { out <- minutes }
    }
}
func main() {
    values := make(chan int)
    done := make(chan struct{})
    go produce([]int{15, -1, 20, 0}, values, done)
    total := 0
    for minutes := range values { total += minutes }
    <-done
    fmt.Println(total)
}
```

